{
  "name": "rf_scan_done_notify",
  "confidence": "medium",
  "docstring": "Completes an RF scan slot, clears/notifies scan-done or abort event 512, and populates a scan-result message header from per-channel RF and scan context tables.",
  "subsystem": "rf",
  "var_renames": {
    "v7": "scan_entry_tbl_base",
    "v8": "rf_scan_ctx_base",
    "v9": "rf_ctx_idx",
    "v13": "scan_result_desc",
    "v14": "scan_state",
    "v16": "event_msg",
    "v17": "event_payload",
    "v22": "timestamp_counter"
  },
  "struct_hints": [
    {
      "offset": 34,
      "meaning": "scan_entry[34] uint8 associated RF context index"
    },
    {
      "offset": 72,
      "meaning": "rf_scan_ctx[72] uint32 scan result descriptor pointer"
    },
    {
      "offset": 4,
      "meaning": "scan_result_desc[4] uint8 scan state"
    },
    {
      "offset": 1224,
      "meaning": "rf_scan_ctx[1224] uint8 scan busy or abort indicator"
    },
    {
      "offset": 106,
      "meaning": "rf_scan_ctx[106] uint8 mode selecting extra measurement fields"
    },
    {
      "offset": 100,
      "meaning": "rf_scan_ctx[100..106] uint16 measurement or timing fields copied to event payload"
    },
    {
      "offset": 108,
      "meaning": "event_payload[108] start of populated scan-result packet header"
    },
    {
      "offset": 130,
      "meaning": "event_payload[130] timestamp or sequence derived from a counter multiplied by 16"
    }
  ]
}
